package xhttp

import (
	"bytes"
	"context"
	"encoding/hex"
	"io"
	"net"
	"testing"
	"time"

	"github.com/sagernet/sing-box/log"
	M "github.com/sagernet/sing/common/metadata"
)

// Baseline-compatible producer regression. The literal is captured separately
// from exact FlClash NewVless (21e6f6ff), NOT generated by sing's serializer.
func TestDynamicDonorDefaultCommand3Production(t *testing.T) {
	for _, dstText := range []string{"192.0.2.1:19302", "example.com:443"} {
		t.Run(dstText, func(t *testing.T) {
			a, b := net.Pipe()
			defer a.Close()
			defer b.Close()
			a.SetDeadline(time.Now().Add(3 * time.Second))
			b.SetDeadline(time.Now().Add(3 * time.Second))
			cfg := dynamicVLESSFixture()
			h := &Outbound{ctx: context.Background(), logger: log.NewNOPFactory().Logger(), dialer: controlFixtureDialer{dial: func(context.Context, string) (net.Conn, error) { return a, nil }}}
			defer h.Close()
			g, err := h.constructGeneration(context.Background(), cfg)
			if err != nil {
				t.Fatal(err)
			}
			h.generation = g
			h.bestCfg = cfg
			h.isInit = true
			dst := M.ParseSocksaddr(dstText)
			// Command3 has NO outer destination. XUDP owns address + session 0.
			want, _ := hex.DecodeString("0000112233445566778899aabbccddeeff00036e8311168ee16d6aa1aa48c64145003c03aabbcc")
			done := make(chan []byte, 1)
			go func() { got := make([]byte, len(want)); io.ReadFull(b, got); done <- got; io.Copy(io.Discard, b) }()
			pc, err := h.ListenPacket(context.Background(), dst)
			if err != nil {
				t.Fatal(err)
			}
			defer pc.Close()
			if _, err = pc.WriteTo([]byte("P"), dst); err != nil {
				t.Fatal(err)
			}
			got := <-done
			if !bytes.Equal(want, got) {
				t.Fatalf("donor constructor default Command3 + E/H mismatch: got=%x want=%x", got, want)
			}
		})
	}
}
